INSERT INTO portfolio_items (id, title, description, category, completed_date, images, services) VALUES
('PF-01', 'Сучасний мінімалізм у передмісті', 'Проєкт комплексного благоустрою ділянки. Було розрівняно рельєф, облаштовано автоматичний полив та укладено преміальний рулонний газон.', 'Ландшафтний дизайн', '2023-09-15', '["data:image/jpeg;base64,"]', '["Укладання газону", "Монтаж автополиву", "Посадка дерев"]'),
('PF-02', 'Каскадний затишок з альпійською гіркою', 'Створено тераси за допомогою підпірних стінок з натурального каменю та висаджено унікальну колекцію багаторічників.', 'Альпінарії та водойми', '2023-05-10', '["data:image/jpeg;base64,"]', '["Терасування", "Створення альпійської гірки"]'),
('PF-03', 'Сад у японському стилі', 'Створення зони релаксу з використанням каменю, гравію та карликових сосен. Додано декоративну водойму.', 'Ексклюзивні проєкти', '2023-11-20', '["data:image/jpeg;base64,"]', '["Дизайн", "Улаштування водойми", "Посадка рослин"]'),
('PF-04', 'Озеленення тераси ресторану', 'Контейнерне озеленення літнього майданчика з використанням вічнозелених чагарників та ампельних квітів.', 'Комерційні об''єкти', '2024-03-10', '["data:image/jpeg;base64,"]', '["Контейнерне озеленення", "Підбір кашпо"]'),
('PF-05', 'Реконструкція старого саду', 'Омолоджуюча обрізка старих яблунь, видалення хворих дерев, вирівнювання ділянки та посів тіньового газону.', 'Догляд за садом', '2023-10-05', '["data:image/jpeg;base64,"]', '["Санітарна обрізка", "Посівний газон"]'),
('PF-06', 'Смарт-сад з автополивом', 'Облаштування ділянки 15 соток з повною автоматизацією: крапельний полив квітників, роторний полив газону, управління зі смартфона.', 'Інженерні системи', '2024-05-01', '["data:image/jpeg;base64,"]', '["Монтаж автополиву", "Смарт-управління"]'),
('PF-07', 'Мавританський газон (квітуча галявина)', 'Замість класичного смарагдового газону ми створили квітучу галявину з польових квітів та злаків.', 'Створення газону', '2023-08-15', '["data:image/jpeg;base64,"]', '["Посів газону", "Підготовка ґрунту"]'),
('PF-08', 'Озеленення заднього двору таунхаусу', 'Компактний дизайн: жива огорожа з туй від сусідів, зона барбекю та рулонний газон.', 'Ландшафтний дизайн', '2024-04-22', '["data:image/jpeg;base64,"]', '["Рулонний газон", "Жива огорожа"]'),
('PF-09', 'Паркова алея житлового комплексу', 'Масштабний проєкт з висадки 50 крупномірних кленів та облаштування пішохідних зон.', 'Комерційні об''єкти', '2023-09-30', '["data:image/jpeg;base64,"]', '["Висадка крупномірів", "Озеленення ЖК"]'),
('PF-10', 'Хвойна колекція', 'Композиція безперервної декоративності з використанням різних видів ялівців, сосен та ялин.', 'Ексклюзивні проєкти', '2024-02-18', '["data:image/jpeg;base64,"]', '["Дендроплан", "Посадка хвойних"]');